const input=$input.first().json;
if(Number(input.chat_id)!==0)return [];
const command=String(input.command||'videos').toLowerCase();
const parts=String(input.args||'').trim().split(/\s+/).filter(Boolean);
const positive=v=>/^[1-9]\d{0,5}$/.test(String(v||''))?Number(v):null;
let valid=true,video_id='',page=1,list_page=1;
if(command==='video'){
 video_id=parts[0]||'';
 valid=/^[A-Za-z0-9_-]{11}$/.test(video_id)&&parts.length<=3;
 page=parts[1]?positive(parts[1]):1;
 list_page=parts[2]?positive(parts[2]):1;
 valid=valid&&Boolean(page)&&Boolean(list_page);
}else{
 valid=command==='videos'&&parts.length<=1;
 page=parts[0]?positive(parts[0]):1;
 valid=valid&&Boolean(page);
}
return [{json:{chat_id:0,command,video_id,page:page||1,list_page:list_page||1,valid,dry_run:input.dry_run===true}}];

const request=$('Normalize Video Request').first().json;
const esc=v=>String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const short=(v,n)=>{const s=String(v??'').replace(/\s+/g,' ').trim();return s.length>n?s.slice(0,n-1)+'…':s;};
const button=(text,data)=>({text,additionalFields:{callback_data:data}});
const keyboard=buttons=>buttons.map(b=>({row:{buttons:Array.isArray(b)?b:[b]}}));
const answer=(text,buttons=[button('🎬 Videos','videos')],extra={})=>[{json:{...request,should_read_summary:false,text,keyboard_rows:keyboard(buttons),...extra}}];
if(!request.valid)return answer('Use /videos to browse captured videos, /videos 2 for another page, or /video VIDEO_ID to reopen a saved summary.');
const events=$('Read Active Event').all().map(i=>i.json).filter(e=>e.event_key&&(e.active===true||e.active==='true'));
if(events.length!==1)return answer('Videos are unavailable: expected exactly one active UFC event.',[button('Main menu','menu')]);
const event=events[0];
const allRows=$input.all().map(i=>i.json).filter(r=>r.video_id&&r.event_key===event.event_key);
const dateValue=r=>Date.parse(r.completed_at||r.published_at||r.createdAt)||0;
const latest=new Map();
for(const row of allRows){const old=latest.get(row.video_id);if(!old||Date.parse(row.updatedAt||0)>Date.parse(old.updatedAt||0))latest.set(row.video_id,row);}
const rows=[...latest.values()].filter(r=>r.transcript_appended===true||r.transcript_appended==='true').sort((a,b)=>dateValue(b)-dateValue(a)||String(a.video_id).localeCompare(String(b.video_id)));
const status=row=>row.analysis_status==='COMPLETED'?'✅ Analysed':row.analysis_status==='PROCESSING'?'⏳ Analysing':row.analysis_status==='FAILED'?'⚠️ Analysis failed':row.analysis_status==='CARD_CHANGED'?'♻️ Analysis needs updating':'📄 Captured · awaiting analysis';
if(request.command==='video'){
 const row=rows.find(r=>r.video_id===request.video_id);
 if(!row)return answer('That video is not in the captured list for the active event. Tap Videos to refresh the list.',[button('🎬 Videos','videos')]);
 const selected={...request,event_name:event.event_name,event_key:event.event_key,spreadsheet_id:event.spreadsheet_id,spreadsheet_url:event.spreadsheet_url,selected_video:row};
 if(row.analysis_status==='COMPLETED'&&event.spreadsheet_id)return [{json:{...selected,should_read_summary:true}}];
 const lines=['<b>'+esc(short(row.channel_name,100))+'</b>',esc(short(row.video_title,180)),'',esc(status(row))];
 if(row.analysis_status==='COMPLETED')lines.push('The event spreadsheet is unavailable, so the saved summary cannot be loaded.');
 else lines.push('The transcript is captured. A saved summary will be available after analysis completes.');
 if(row.analysis_error)lines.push('',esc(short(row.analysis_error,240)));
 return answer(lines.join('\n'),[button('🎬 Back to videos','videos '+request.list_page),{text:'▶️ Watch video',additionalFields:{url:'https://www.youtube.com/watch?v='+row.video_id}}],selected);
}
if(!rows.length)return answer('<b>Captured videos</b>\n'+esc(short(event.event_name,180))+'\n\nNo videos have been captured for this event yet.',[button('Refresh','videos'),button('Main menu','menu')]);
const size=8,pages=Math.ceil(rows.length/size),page=Math.min(request.page,pages),start=(page-1)*size,visible=rows.slice(start,start+size);
const done=rows.filter(r=>r.analysis_status==='COMPLETED').length;
const lines=['<b>Captured videos</b>',esc(short(event.event_name,180)),rows.length+' captured · '+done+' analysed','Page '+page+' of '+pages,'','Tap a video button to reopen its saved summary.'];
const controls=[];
for(const [i,row] of visible.entries()){
 const number=start+i+1;
 lines.push('','<b>'+number+'. '+esc(short(row.channel_name,80))+'</b> — '+esc(status(row)),esc(short(row.video_title,140)));
 controls.push(button(number+'. '+short(row.channel_name||'Video',32)+(row.analysis_status==='COMPLETED'?' · Summary':' · Status'),'video '+row.video_id+' 1 '+page));
}
const nav=[];
if(page>1)nav.push(button('← Previous','videos '+(page-1)));
if(page<pages)nav.push(button('Next →','videos '+(page+1)));
if(nav.length)controls.push(nav);
controls.push([button('Refresh','videos '+page),button('Main menu','menu')]);
return answer(lines.join('\n'),controls,{list_page:page,event_key:event.event_key,video_count:rows.length,analysed_count:done});

const source=$input.first().json;
const esc=v=>String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const buttons=(source.keyboard_rows||[]).flatMap(r=>r.row?.buttons||[]);
const callbackButtons=buttons.filter(b=>b.additionalFields?.callback_data);
const links=buttons.filter(b=>b.additionalFields?.url&&/^https:\/\//.test(b.additionalFields.url));
let text=source.text;
if(links.length)text+='\n\n'+links.map(b=>'<a href="'+esc(b.additionalFields.url)+'">'+esc(b.text)+'</a>').join(' · ');
if(!callbackButtons.length)callbackButtons.push({text:'Main menu',additionalFields:{callback_data:'menu'}});
const keyboard_rows=callbackButtons.slice(0,12).map(button=>({row:{buttons:[button]}}));
return [{json:{...source,text,keyboard_rows,keyboard_count:keyboard_rows.length}}];

const view=$('Choose Video View').first().json;
const row=view.selected_video;
const esc=v=>String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const short=(v,n)=>{const s=String(v??'').replace(/\s+/g,' ').trim();return s.length>n?s.slice(0,n-1)+'…':s;};
const rowsOf=name=>$(name).all().map(i=>i.json);
const pickData=rowsOf('Read Saved Picks'),propData=rowsOf('Read Saved Props');
const keyboard_rows=[];
const buttons=[];
const back={text:'🎬 Back to videos',additionalFields:{callback_data:'videos '+view.list_page}};
const watch={text:'▶️ Watch video',additionalFields:{url:'https://www.youtube.com/watch?v='+row.video_id}};
const sheet={text:'📄 Spreadsheet',additionalFields:{url:view.spreadsheet_url||'https://docs.google.com/spreadsheets/d/'+view.spreadsheet_id+'/edit'}};
if([...pickData,...propData].some(r=>r.error)){
 return [{json:{...view,text:'Could not load the saved summary from the event spreadsheet. Try again in a moment.',keyboard_rows:[{row:{buttons:[back,sheet]}}],summary_available:false}}];
}
const picks=pickData.filter(p=>p.video_id===row.video_id&&p.event_key===view.event_key&&p.picked_fighter).sort((a,b)=>Number(a.fight_order||999)-Number(b.fight_order||999));
const props=propData.filter(p=>p.video_id===row.video_id&&p.event_key===view.event_key&&p.market);
const header=['<b>Saved video summary</b>','<b>'+esc(short(row.channel_name,70))+'</b>',esc(short(row.video_title,120)),esc(short(view.event_name,120)),picks.length+' picks · '+props.length+' props'].join('\n');
function method(pick){
 const priorities=['method_and_round','method_of_victory','inside_distance','winning_round'];
 const matching=props.filter(p=>Number(p.fight_order)===Number(pick.fight_order)&&p.fighter===pick.picked_fighter);
 let p;
 for(const market of priorities){p=matching.find(p=>p.market===market);if(p)break;}
 if(!p)return 'to win';
 const round=p.round?' in R'+p.round:p.round_range?' in '+short(p.round_range,20):'';
 if(p.method==='KO_TKO')return 'by KO/TKO'+round;
 if(p.method==='submission')return 'by submission'+round;
 if(p.method==='decision')return 'by decision';
 if(p.market==='inside_distance')return 'inside the distance'+round;
 if(p.market==='winning_round')return 'to win'+round;
 return 'to win';
}
const sections=[];
if(picks.length)sections.push('<b>Fight-card picks</b>');
for(const p of picks){
 const opponent=p.picked_fighter===p.fighter_a?p.fighter_b:p.fighter_a;
 const confidence=Number(p.confidence_score);
 let text='<b>'+Number(p.fight_order||0)+'. '+esc(short(p.picked_fighter,55))+' '+esc(method(p))+'</b> over '+esc(short(opponent,55));
 if(Number.isFinite(confidence)&&confidence>0)text+=' — '+confidence+'/10';
 if(p.reasoning_summary)text+='\n↳ '+esc(short(p.reasoning_summary,150));
 sections.push(text);
}
const recommended=props.filter(p=>['lean','recommended_bet','best_bet'].includes(p.recommendation_strength)).sort((a,b)=>Number(a.fight_order||999)-Number(b.fight_order||999));
if(recommended.length)sections.push('<b>Betting leans and recommendations</b>');
for(const p of recommended)sections.push('• Fight '+Number(p.fight_order||0)+': '+esc(short(p.selection,140))+(p.odds_mentioned?' at '+esc(short(p.odds_mentioned,20)):'')+' — '+esc(String(p.recommendation_strength).replace(/_/g,' ')));
if(!sections.length)sections.push('No saved picks or betting recommendations were found. Open the spreadsheet to inspect the extraction.');
const pages=[];let chunk='';
const budget=Math.max(1200,3600-header.length);
for(const section of sections){
 const next=chunk?chunk+'\n\n'+section:section;
 if(next.length>budget&&chunk){pages.push(chunk);chunk=section;}else chunk=next;
}
if(chunk)pages.push(chunk);
const page=Math.min(view.page,pages.length),nav=[];
if(page>1)nav.push({text:'← Previous',additionalFields:{callback_data:'video '+row.video_id+' '+(page-1)+' '+view.list_page}});
if(page<pages.length)nav.push({text:'More →',additionalFields:{callback_data:'video '+row.video_id+' '+(page+1)+' '+view.list_page}});
if(nav.length)keyboard_rows.push({row:{buttons:nav}});
keyboard_rows.push({row:{buttons:[back,watch]}},{row:{buttons:[sheet]}});
return [{json:{...view,text:header+'\nPage '+page+' of '+pages.length+'\n\n'+pages[page-1],keyboard_rows,summary_available:picks.length>0||props.length>0,pick_count:picks.length,prop_count:props.length,summary_page:page,summary_pages:pages.length}}];
